const $=s=>document.querySelector(s), KEY='tempo-safari-demo-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY))||{}}catch{state={}}state={profile:null,saved:false,reps:0,completed:0,...state};
let step=0,draft={sport:'Badminton',level:'Getting back into it',name:''},clipURL=null,restEnd=0,remaining=45,restRunning=false;
const icons={today:'<path d="m3 11 9-8 9 8v10h-6v-6H9v6H3z"/>',review:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="m10 9 5 3-5 3zM8 2v3m8-3v3"/>',plan:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M8 12h8m-8 4h5"/>',you:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',check:'<path d="m5 12 4 4L20 5"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.check}</svg>`;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Storage is unavailable; changes last for this visit.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();
function go(tab){if(location.hash===`#${tab}`)render();else location.hash=tab}
function render(){const tab=location.hash.slice(1)||'today';const active=['today','review','plan','you'].includes(tab)?tab:tab==='example'?'review':'today';$('nav').innerHTML=['today','review','plan','you'].map(name=>`<a href="#${name}" ${name===active?'class="active" aria-current="page"':''}>${icon(name)}${name==='you'?'You':name[0].toUpperCase()+name.slice(1)}</a>`).join('');if(!state.profile){onboarding();return}const views={today,review,example,plan,you};$('#screen').innerHTML=(views[tab]||today)();$('#screen').scrollTop=0;$('#screen').className='screen-enter';bind();updateTimer()}
function onboarding(){const sports=['Badminton','Tennis'],levels=['Finding my feet','Getting back into it','Playing regularly'];$('#screen').innerHTML=`<div class="onboarding-progress">${[0,1,2].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><span class="eyebrow">LET’S FIND YOUR TEMPO · ${step+1}/3</span><h1>${['Your court.<br>Your next chapter.','A little about<br>your game.','One session.<br>One clear focus.'][step]}</h1><p class="lead">${['Pick the sport you want to work on.','We’ll start at your pace.','This demo explores a comfortable overhead reach. Your profile stays on this device.'][step]}</p>${step===0?sports.map(s=>`<button class="choice" data-sport="${s}" aria-pressed="${draft.sport===s}">${s}<span style="float:right">↗</span></button>`).join(''):step===1?levels.map(s=>`<button class="choice" data-level="${s}" aria-pressed="${draft.level===s}">${s}</button>`).join(''):'<label class="field" for="name">What should we call you? (optional)</label><input type="text" id="name" maxlength="30" autocomplete="given-name" placeholder="Your first name"><div class="hero"><span class="tag">YOUR FIRST FOCUS</span><h2>Give your overhead room to move.</h2><p>Explore a sample review, then try a simple practice drill.</p></div>'}<button class="primary" id="onboard-next">${step===2?'Let’s get started':'Continue'} ${icon('arrow')}</button>${step>0?'<button class="text-button" id="onboard-back">Back</button>':''}<p class="note">Interactive prototype. Example coaching only. No live analysis or Health connection.</p>`;document.querySelectorAll('[data-sport]').forEach(b=>b.onclick=()=>{draft.sport=b.dataset.sport;onboarding()});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{draft.level=b.dataset.level;onboarding()});$('#onboard-next').onclick=()=>{if(step<2){step++;onboarding()}else{draft.name=$('#name').value.trim();state.profile={...draft};save();go('today');render()}};if($('#onboard-back'))$('#onboard-back').onclick=()=>{step--;onboarding()}}
function today(){return `<span class="eyebrow">A LITTLE BETTER, EVERY SESSION</span><h1>${state.profile.name?`Hey, ${esc(state.profile.name)}.`:'Your next better shot.'}</h1><p class="lead">You bring the effort.<br>We’ll help you find the focus.</p><div class="hero"><span class="tag">${esc(state.profile.sport.toUpperCase())} · PRACTICE FOCUS</span><h2>Make space for<br>your overhead.</h2><p>One movement. A few thoughtful reps.<br>A calmer, more comfortable reach.</p><a class="primary" href="#review">Review a stroke ${icon('arrow')}</a></div><div class="section-head"><h2>A small step today</h2><span class="pill">5 MIN</span></div><div class="card row"><div class="round">${icon('plan')}</div><div class="grow"><h3>Reach. Pause. Reset.</h3><p class="small">10 controlled overhead reps</p></div><button class="text-button" data-action="open-plan" aria-label="Open practice plan">↗</button></div><div class="section-head"><h2>Your rhythm</h2><span class="small">ON THIS DEVICE</span></div><div class="stats"><div class="stat"><strong>${state.completed}</strong><span>drills completed</span></div><div class="stat"><strong>${state.saved?'1':'0'}</strong><span>saved focus</span></div><div class="stat"><strong>—</strong><span>live heart rate</span></div></div><p class="note">This is a tappable demo. Try the example review to see the coaching flow.</p>`}
function review(){return `<span class="eyebrow">SEE IT. FEEL IT. IMPROVE IT.</span><h1>A fresh look<br>at your stroke.</h1><p class="lead">A short clip is a good place to start.</p><label class="upload">${icon('upload')}<strong>Choose or record a clip</strong><span class="small">Local preview only · stays on your device</span><input id="clip" type="file" accept="video/*" capture="environment" aria-label="Choose or record a video"></label><div id="clip-preview"></div><div class="section-head"><h2>Try a coaching review</h2><span class="pill">EXAMPLE</span></div><div class="card"><h3>Overhead clear · badminton</h3><p style="margin-top:8px">Walk through a measured example and save a single practice focus.</p><a class="primary" href="#example">Open example review ${icon('arrow')}</a></div><p class="note">This browser demo cannot analyse your clip. The example uses a separate public badminton video; its result is never applied to your video.</p>`}
function example(){return `<button class="text-button" data-action="back-review">← Back to review</button><br><span class="eyebrow">EXAMPLE REVIEW · BADMINTON</span><h1>Reach a little<br>more freely.</h1><p class="lead">One focus for the next session: make room for your overhead reach.</p><div class="example-figure"><span class="eyebrow">ESTIMATED ELBOW EXTENSION</span><div class="big">163.64<small>°</small></div><p class="small">25 usable frames · public example clip</p></div><p class="note">An earlier backend test produced this estimate. Camera angle and pose tracking affect it; it has not been validated against ground truth. No analysis is running here.</p><div class="section-head"><h2>Your one focus</h2><button class="text-button" data-action="listen">◖ Listen</button></div><div class="card"><h3>Reach. Pause. Reset.</h3><p style="margin-top:8px">Try a slow overhead shadow swing. Reach comfortably, pause, then reset. Keep it relaxed; don’t force your elbow straight.</p><ol class="steps"><li>Start side-on with room above you.</li><li>Move slowly through a comfortable overhead reach.</li><li>Reset fully. Repeat 10 times at your own pace.</li></ol><button class="primary" data-action="save-drill">${state.saved?'Open saved drill':'Save this drill'} ${icon('arrow')}</button></div><p class="small" style="margin-top:16px">Listen uses your device’s speech voice. <a href="https://www.youtube.com/watch?v=5tG-krOy1ro" target="_blank" rel="noopener">View example video source ↗</a></p>`}
function plan(){if(!state.saved)return `<span class="eyebrow">SMALL STEPS. REAL RHYTHM.</span><h1>Your practice,<br>with a purpose.</h1><div class="hero"><span class="tag">A FOCUS TO BUILD ON</span><h2>Start with<br>one clear cue.</h2><p>Explore the example review, then save the drill you’d like to practise.</p><a href="#example" class="primary">Find your first drill ${icon('arrow')}</a></div>`;return `<span class="eyebrow">YOUR SAVED PRACTICE</span><h1>A little room.<br>A better reach.</h1><p class="lead">Reach. Pause. Reset. Move at your pace.</p><div class="card"><div class="row"><span class="tag" style="background:#eee5d6">SHADOW SWING</span><span class="small grow" style="text-align:right">SELF-COUNTED REPS</span></div><div class="counter">${state.reps}<small> / 10</small></div><div class="rep-buttons"><button class="secondary" data-action="minus" aria-label="Remove one repetition" ${state.reps===0?'disabled':''}>−</button><button class="primary" data-action="rep" ${state.reps>=10?'disabled':''}>${state.reps>=10?'Set complete ✓':'+ Count a rep'}</button></div><p class="small" style="margin-top:12px">A manual counter, not movement detection.</p></div><div class="card row"><div class="grow"><h3>A moment to reset</h3><div class="timer" id="timer">0:45</div></div><button class="text-button" data-action="timer" id="timer-button">${restRunning?'Pause':'Start rest'}</button><button class="text-button" data-action="reset-timer" aria-label="Reset rest timer">↺</button></div><button class="primary" data-action="finish" ${state.reps<10?'disabled':''}>Finish practice ${icon('check')}</button><div class="section-head"><h2>Make a little time</h2><span class="pill">OPTIONAL</span></div><div class="card"><label class="field" for="day" style="margin-top:0">Next practice</label><select id="day">${['Tomorrow','In 2 days','In 3 days'].map((s,i)=>`<option value="${i+1}" ${state.practiceDays===i+1?'selected':''}>${s}</option>`).join('')}</select><button class="secondary" data-action="calendar">Download calendar reminder</button><p class="small" style="margin-top:10px">Opens a calendar file for you to review and add.</p></div>`}
function you(){return `<span class="eyebrow">YOUR GAME. YOUR PACE.</span><h1>${esc(state.profile.name||'Your Tempo')}.</h1><p class="lead">${esc(state.profile.sport)} · ${esc(state.profile.level)}</p><div class="section-head"><h2>Watch connection</h2><span class="pill">NOT CONNECTED</span></div><div class="card"><div class="stats"><div class="stat"><strong>— <small>bpm</small></strong><span>No Watch reading received</span></div></div><div class="divider"></div><p>Safari cannot read Apple Health directly. Tempo’s current route uses an iPhone Shortcut to send Apple Watch readings to its HTTPS receiver.</p><button class="text-button" data-action="watch-info">How the connection works ↗</button></div><div class="section-head"><h2>Keep Tempo close</h2></div><div class="card row"><div class="round">${icon('upload')}</div><div class="grow"><h3>Add to Home Screen</h3><p class="small">Open like an app from Safari</p></div><button class="text-button" data-action="install" aria-label="Show installation guide">↗</button></div><div class="section-head"><h2>About this demo</h2></div><p>Your profile, saved drill and rep count stay in this browser’s local storage. Clips are previewed on this device and are not uploaded. Clearing website data removes your progress.</p><p class="note">No sign-in, live AI, native Health access or backend connection. Example feedback demonstrates the intended coaching flow.</p><button class="text-button" data-action="reset">Reset demo and profile</button>`}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));if($('#clip'))$('#clip').onchange=e=>{const file=e.target.files[0];if(!file)return;if(clipURL)URL.revokeObjectURL(clipURL);clipURL=URL.createObjectURL(file);$('#clip-preview').innerHTML='<video controls playsinline aria-label="Your local video preview"></video><p class="note">Your clip is ready to preview locally. To explore feedback, open the separate example below.</p>';$('#clip-preview video').src=clipURL}}
function action(name){switch(name){case'open-plan':go(state.saved?'plan':'example');break;case'back-review':go('review');break;case'save-drill':state.saved=true;save();go('plan');toast('Drill saved on this device');break;case'rep':state.reps=Math.min(10,state.reps+1);save();render();break;case'minus':state.reps=Math.max(0,state.reps-1);save();render();break;case'timer':if(restRunning){remaining=Math.max(0,Math.ceil((restEnd-Date.now())/1000));restRunning=false}else{if(!remaining)remaining=45;restEnd=Date.now()+remaining*1000;restRunning=true}updateTimer();break;case'reset-timer':restRunning=false;remaining=45;updateTimer();break;case'finish':if(state.reps<10)return;state.completed++;state.reps=0;save();render();modal('<span class="eyebrow">THAT’S A GOOD STEP</span><h2 style="margin-top:12px">Practice, done.</h2><p>You completed 10 self-counted reps. Keep the same comfortable reach in mind next time you play.</p>');break;case'listen':if(!('speechSynthesis'in window)){toast('Device voice unavailable. Read your focus below.');return}speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance('Your focus: reach, pause, reset. Try a slow overhead shadow swing. Reach comfortably, pause, then reset. Keep it relaxed. Do not force your elbow straight.'));break;case'install':modal('<h2>Tempo, one tap away.</h2><ol class="steps"><li>Open this site in Safari on your iPhone.</li><li>Tap Share, then Add to Home Screen. You may need to scroll through the actions.</li><li>Turn on Open as Web App if shown, then tap Add.</li></ol><p>After your first visit, the app shell can open offline. External links still need a connection.</p>');break;case'watch-info':modal('<h2>From Watch to Tempo.</h2><ol class="steps"><li>Apple Watch syncs its readings into Health on your paired iPhone.</li><li>An authorised Shortcut reads the latest sample and its timestamp, then posts to the HTTPS receiver.</li><li>The Tempo relay associates the sample with a player and session before storing it in sports_coach_db.</li></ol><p>This mockup does not run that connection. Keep receiver access keys out of public demo pages.</p>');break;case'reset':modal('<h2>Start fresh?</h2><p>This removes only this demo’s local profile and practice progress.</p><button class="secondary" id="confirm-reset">Reset this demo</button>');$('#confirm-reset').onclick=()=>{state={profile:null,saved:false,reps:0,completed:0};step=0;restRunning=false;remaining=45;save();$('#modal').close();render()};break;case'calendar':calendar();break}}
function updateTimer(){let seconds=restRunning?Math.max(0,Math.ceil((restEnd-Date.now())/1000)):remaining;if(restRunning&&seconds===0){restRunning=false;remaining=0;toast('Rest finished. Continue when you’re ready.')}if($('#timer'))$('#timer').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;if($('#timer-button'))$('#timer-button').textContent=restRunning?'Pause':seconds?'Start rest':'Start again'}setInterval(updateTimer,500);
function calendar(){state.practiceDays=Number($('#day').value);save();const start=new Date();start.setDate(start.getDate()+state.practiceDays);start.setHours(18,0,0,0);const end=new Date(start.getTime()+5*60000),stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Tempo//Practice Demo//EN','BEGIN:VEVENT',`UID:${Date.now()}@tempo-demo`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(start)}`,`DTEND:${stamp(end)}`,'SUMMARY:Tempo - Reach. Pause. Reset.','DESCRIPTION:10 slow comfortable overhead shadow swings. Self-guided practice.','END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([data],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='tempo-practice.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Calendar file prepared. Review before adding.')}
window.addEventListener('hashchange',render);window.addEventListener('pagehide',()=>{if(clipURL)URL.revokeObjectURL(clipURL)});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
